import{_ as a,H as s,f as t,i as n}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"解锁Cursor：AI到底在Golang开发中能帮助我们什么？","description":"","frontmatter":{},"headers":[{"level":2,"title":"工具选择","slug":"工具选择","link":"#工具选择","children":[{"level":3,"title":"Tab","slug":"tab","link":"#tab","children":[]},{"level":3,"title":"Inline Chat/Edit","slug":"inline-chat-edit","link":"#inline-chat-edit","children":[]},{"level":3,"title":"Chat","slug":"chat","link":"#chat","children":[]},{"level":3,"title":"Composer","slug":"composer","link":"#composer","children":[]}]},{"level":2,"title":"模型选择","slug":"模型选择","link":"#模型选择","children":[]},{"level":2,"title":"神秘的 @ 符号","slug":"神秘的-符号","link":"#神秘的-符号","children":[{"level":3,"title":"Files","slug":"files","link":"#files","children":[]},{"level":3,"title":"Folders","slug":"folders","link":"#folders","children":[]},{"level":3,"title":"Code","slug":"code","link":"#code","children":[]},{"level":3,"title":"Docs","slug":"docs","link":"#docs","children":[]},{"level":3,"title":"Git","slug":"git","link":"#git","children":[]},{"level":3,"title":"Notepad","slug":"notepad","link":"#notepad","children":[]},{"level":3,"title":"Suggested","slug":"suggested","link":"#suggested","children":[]},{"level":3,"title":"Codebase","slug":"codebase","link":"#codebase","children":[]},{"level":3,"title":"Web","slug":"web","link":"#web","children":[]}]},{"level":2,"title":"Cursor 如何赋能 Golang 编程","slug":"cursor-如何赋能-golang-编程","link":"#cursor-如何赋能-golang-编程","children":[{"level":3,"title":"场景 1：批量操作","slug":"场景-1-批量操作","link":"#场景-1-批量操作","children":[]},{"level":3,"title":"场景2：单元测试","slug":"场景2-单元测试","link":"#场景2-单元测试","children":[]},{"level":3,"title":"场景3：源码阅读","slug":"场景3-源码阅读","link":"#场景3-源码阅读","children":[]},{"level":3,"title":"场景4：代码改写","slug":"场景4-代码改写","link":"#场景4-代码改写","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]}],"relativePath":"手把手带你写一个Web框架/解锁Cursor：AI到底在Golang开发中能帮助我们什么？.md","filePath":"手把手带你写一个Web框架/解锁Cursor：AI到底在Golang开发中能帮助我们什么？.md","lastUpdated":1779820017000}'),i={name:"手把手带你写一个Web框架/解锁Cursor：AI到底在Golang开发中能帮助我们什么？.md"};function o(p,e,r,l,c,E){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="解锁cursor-ai到底在golang开发中能帮助我们什么" tabindex="-1">解锁Cursor：AI到底在Golang开发中能帮助我们什么？ <a class="header-anchor" href="#解锁cursor-ai到底在golang开发中能帮助我们什么" aria-label="Permalink to &quot;解锁Cursor：AI到底在Golang开发中能帮助我们什么？&quot;">​</a></h1><p>你好，我是轩脉刃。</p><p>距离 2021 年专栏上线，已经有 3 年时间了。这期间，互联网发生了翻天覆地的变化，Golang 编程领域也不例外。Golang 的版本从 1.16 升级到了 1.23、引入了范式，并且 Go Mod 彻底取代 Go Path 模式成为包管理器，Golang 引入了工作区模式等。而这些诸多变化，恐怕都及不上最热的 AI 带给编程领域的变化。</p><p>ChatGPT 3.5 自 2022 年问世以来，生成式 AI 彻底引发了各个行业大变革，AI 编程一直是热度很高的话题。“人人都是 AI 程序员”“使用 AI 构造一人公司”“AI 完全可以替代程序员” 等一直是大家讨论不休的话题。并且目前为止，AI 替代程序员编程已经不仅仅局限在讨论和想象层次了，国内所有大厂都有自己的 AI 代码编写工具，并已经逐步应用。</p><p>作为一线程序员，我也一直在研究 AI 到底能对 Golang 开发有什么帮助，亲身尝试过 Tabnine、GitHub Copilot、ChatGPT 等工具。近半年来，我越来越发现插件模式的 AI 编码工具已经不能很好满足我的编码需求了，我更希望的是一个以项目为单位，能按照我的需求创建、阅读、编写项目的独立 IDE。因此，我的 AI 编码工具逐渐从 GitHub Copilot + JetBrains 转为了 Cursor。</p><p>在使用 Cursor 开发 Golang 的过程中，我积攒了很多技巧，也踩了很多“坑”，想一次都分享给你。同时，我也想以 Cursor 为例，讲讲编码工具是如何赋能 Golang 编程的。</p><blockquote><p>说明：本节使用的 Cursor 为版本 0.44.6，且开通了 pro 版的功能限制。</p><p>最新消息：截止 2024 年 12 月 22 日，Cursor 已成功完成 1 亿美元的 B 轮融资，此轮融资后的估值达到了 26 亿美元。</p></blockquote><h2 id="工具选择" tabindex="-1">工具选择 <a class="header-anchor" href="#工具选择" aria-label="Permalink to &quot;工具选择&quot;">​</a></h2><p>Cursor 是几位麻省理工学院（MIT）的学生在 2022 年创立的一家公司 （cursor.Inc） 的产品，它并不是从头开始做一款 IDE，而是站在巨人的肩膀上，从 VSCode 项目 fork 出来源码，并且直接进行魔改，它不是以 VSCode 的插件形态展示，而是一个完整的兼容了 VSCode 所有插件和配置的 IDE 工具。</p><p>从插件到全新 IDE 工具，别看只是这么一小步的变化，对于编码的帮助却是巨大的。它让 AI 渗透到了编码的各种场景中，为各种场景提升效果。</p><p>总结下来，Cursor 目前提供了不同等级的编码辅助方式：</p><ul><li><p>Tab</p></li><li><p>Inline Chat/Edit</p></li><li><p>Chat</p></li><li><p>Composer</p></li></ul><p>了解这些辅助方式是上手使用 Cursor 的第一步。</p><h3 id="tab" tabindex="-1">Tab <a class="header-anchor" href="#tab" aria-label="Permalink to &quot;Tab&quot;">​</a></h3><p>Tab 就是自动补全功能，我们在编写代码的过程中，Cursor 会根据上下文推测我们接下来要输出的代码是什么，并且在 IDE 中使用灰色将建议补充的代码展示出来，我们只需要使用 Tab 键就能让其自动完成。在日常编码过程中，这个功能是最常用的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/da74282bb1fb022cf08d2fc95472cbef.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/da74282bb1fb022cf08d2fc95472cbef.png" alt="图片"></a></p><h3 id="inline-chat-edit" tabindex="-1">Inline Chat/Edit <a class="header-anchor" href="#inline-chat-edit" aria-label="Permalink to &quot;Inline Chat/Edit&quot;">​</a></h3><p>Inline Chat/Edit 是当我们选中 IDE 中一段代码的时候，系统会弹出 Chat/Edit 的内嵌框来针对这一段代码进行讨论和修改。它的好处是能将 Cursor 的改动限制在这一段代码中，而不会影响到其他的代码。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/863600974cc990a8528aa2176be3e9aa.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/863600974cc990a8528aa2176be3e9aa.png" alt="图片"></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/f0aa247c4314c65f89321c53d9e54a2d.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/f0aa247c4314c65f89321c53d9e54a2d.png" alt="图片"></a></p><p>对于 Inline Chat/Edit 的使用，Follow-up instrctions 是一个经常被忽略的功能。当 Cursor 按照提示增加的代码逻辑有一些瑕疵时，我们不要急着回滚 Cursor 的操作，而是可以使用 Follow-up instrctions 功能来追加提示和修改。Cursor 就会将两个提示词合成在一起，再进行一次变更。这个功能在无法一下子写出长且完整的 Cursor 提示词的情况下非常有效果。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/a8b688a0643280050ca1d5400cc844c9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/a8b688a0643280050ca1d5400cc844c9.png" alt="图片"></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/cc1830a671b601639b623aeb95e4e37b.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/cc1830a671b601639b623aeb95e4e37b.png" alt="图片"></a></p><h3 id="chat" tabindex="-1">Chat <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;Chat&quot;">​</a></h3><p>Chat 和 Composer 是以面板的形式内嵌在 IDE 右侧的。和名字一样，在 Chat 面板中，我们可以和模型进行对话交流。这里的交流并不会影响左侧代码区的代码，在 Chat 的对话框中，我们可以问任意的问题。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/dfec12503883698fdbab88f05144c25d.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/dfec12503883698fdbab88f05144c25d.png" alt="图片"></a></p><p>在 Chat 对话框中，我们就能选择这次对话聊天使用的模型。关于模型的选择，我们在后面再详细聊。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/e85884d9aede6c1c428488a81a449c69.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/e85884d9aede6c1c428488a81a449c69.png" alt="图片"></a></p><h3 id="composer" tabindex="-1">Composer <a class="header-anchor" href="#composer" aria-label="Permalink to &quot;Composer&quot;">​</a></h3><p>Composer 是 Cursor 团队精心打造的一项全新功能，可以说，没有用过 Composer 就不算真正用过 Cursor。</p><p>Composer 的面板和 Chat 的面板基本一模一样。 但是 Composer 的强大之处在于其不局限于一个文件的处理，可以同时处理多个文件，同时针对多个文件进行辅助开发，甚至你可以让它从零开始帮你创建多个文件，进而构造一个项目。对于需要处理大型复杂代码库的中高级开发者而言，无论是进行代码组件的修改、变量的跨文件转换，还是统一应用样式变更，Composer 都能完美满足你的需求。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/9ab6f5340f7b9bafe468dd90b5026dda.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/9ab6f5340f7b9bafe468dd90b5026dda.png" alt="图片"></a></p><h2 id="模型选择" tabindex="-1">模型选择 <a class="header-anchor" href="#模型选择" aria-label="Permalink to &quot;模型选择&quot;">​</a></h2><p>Cursor 是一个集成了多种模型的 AI 编码 IDE，模型对于它来说，就像是底座引擎。Cursor 支持的模型非常多：</p><ul><li><p>claude-3.5-sonnet-20241022</p></li><li><p>claude-3.5</p></li><li><p>cursor-small</p></li><li><p>gemini-2.0</p></li><li><p>gpt-4-turbo-2024-04-09</p></li><li><p>gpt-4o</p></li><li><p>o1</p></li><li><p>…</p></li></ul><p>这些模型都是不同大公司来支持维护的。其中，Claude 隶属于 Anthropic 公司，Gemini 隶属于 Google 公司，GPT 隶属于 OpenAI 公司。</p><p>我使用得最多的是 Claude 3.5 模型，在很长一段时间的各种测评中，Claude 在辅助编码方面的得分一直是最高的。</p><blockquote><p>具体可以参考他们在 2024 年 6 月份发布的 <a href="https://www.anthropic.com/news/claude-3-5-sonnet" target="_blank" rel="noreferrer">测评报告</a>。</p></blockquote><p>Cursor 的联合创始人 Aman Sanger 在 Lex Fridman 10 月的播客上对 Anthropic 大加称赞：“得益于对用户需求更深入的理解，最新版的 Claude 3.5 Sonnet 可以说是当前 <strong>最佳</strong> 的编程工具。”</p><p>为了让模型的回答更符合我们的要求，我们会在每次请求中设置 System Prompt。在 Cursor 中，我们也可以为模型设置一些默认提示词，这些提示词能有效规范模型的行为，称为 rule。</p><p>Cursor 的 rule 设置包括全局 rule 和项目 .cursorrules。在配置文件中，我们设置全局 rule，而对于不同项目，我们可以在项目中创建 .cursorrules 文件，为该项目设置特定的提示词。最终使用的提示词，是这两个地方的提示词合并后送入模型中的。</p><p>因此，全局提示词应尽量设置为通用的，与具体语言项目无关；而项目的 .cursorrules 提示词则应尽量包含项目的特性。以下是我使用的全局 rule：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Bug Fixes:</span></span>
<span class="line"><span>   - Analyze the problem thoroughly before suggesting fixes</span></span>
<span class="line"><span>   - Provide precise, targeted solutions</span></span>
<span class="line"><span>   - Explain the root cause of the bug</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. Keep It Simple:</span></span>
<span class="line"><span>   - Prioritize readability and maintainability</span></span>
<span class="line"><span>   - Avoid over-engineering solutions</span></span>
<span class="line"><span>   - Use standard libraries and patterns when possible</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. Code Changes:</span></span>
<span class="line"><span>   - Propose a clear plan before making changes</span></span>
<span class="line"><span>   - Do not alter unrelated files</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Remember to always consider the context and specific requirements of each project.</span></span>
<span class="line"><span>Remember use chinese reply all question.</span></span></code></pre></div><p>这个全局 rule 主要是为了提示 Cursor，尽量生成无 Bug 且简单可维护的代码，并且不要修改与需求无关的代码，同时尽量使用中文回答所有问题。</p><p>关于项目的提示词，每个项目，每个语言都不一样，这里无法给出一个统一的提示词。建议你参考 <a href="https://cursor.directory/" target="_blank" rel="noreferrer">https://cursor.directory/</a> 网站，其中对各种语言都有提示词的模板。比如 Golang 的提示词可以参考： <a href="https://cursor.directory/go-api-standard-library-1-22" target="_blank" rel="noreferrer">https://cursor.directory/go-api-standard-library-1-22</a>。</p><h2 id="神秘的-符号" tabindex="-1">神秘的 @ 符号 <a class="header-anchor" href="#神秘的-符号" aria-label="Permalink to &quot;神秘的 @ 符号&quot;">​</a></h2><p>在 Cursor 使用过程中，我们在 Chat 和 Composer 面板中输入 @ 符号，就会弹出很多关联的信息。 <strong>了解并熟练使用这些信息，是使用好 Cursor 的关键</strong>。下面我结合实际的场景来演示下这些 @ 符号都可以怎么使用。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/4a262d699fa7960f9da2767309089424.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/4a262d699fa7960f9da2767309089424.png" alt="图片"></a></p><h3 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h3><p>Files 表示我们可以在描述中具体说明哪个文件或者哪些文件。</p><p>比如，我们现在需要 Composer 来修改 api_goroutine.go 这个文件，将其中的所有函数都带上注释说明。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/ff1f8d3c8639f4fd4f22ef900951d300.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/ff1f8d3c8639f4fd4f22ef900951d300.png" alt="图片"></a></p><h3 id="folders" tabindex="-1">Folders <a class="header-anchor" href="#folders" aria-label="Permalink to &quot;Folders&quot;">​</a></h3><p>Folder 能准确代表一个文件夹，我们可以这样描述：在某个文件夹下增加一个模块，具体参考某个文件夹内容等。这样就能将我们的改动限定在具体的文件夹中了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/6ca327546402cd277813f6dd9f34a071.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/6ca327546402cd277813f6dd9f34a071.png" alt="图片"></a></p><p>我们看到，Composer 自动在 module 文件夹下创建了 student 文件夹，并参考 demo 实现了 5 个文件，实现了 DDD 业务模型，效果如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/275690758b8d7c2843dd6207263ab9dd.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/275690758b8d7c2843dd6207263ab9dd.png" alt="图片"></a></p><h3 id="code" tabindex="-1">Code <a class="header-anchor" href="#code" aria-label="Permalink to &quot;Code&quot;">​</a></h3><p>Code 能具体代表某个函数，这是我使用最多的逻辑。我们为某个函数写个单元测试，修改调试某个函数，只要在提示词中使用 Code，就能很方便将 Cursor 的改动限定在某个函数中。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/9ec80b5155bd90787b1a07a4c074ayyd.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/9ec80b5155bd90787b1a07a4c074ayyd.png" alt="图片"></a></p><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><p>Docs 是一个很强大的能力。我们在开发过程中经常需要引用一些第三方的接口，而这些第三方的接口是有官方文档的。比如下面我要创建一个gohade 框架的 provider，我们希望 Cursor 先阅读下官方文档 <a href="https://github.com/gohade/hade/blob/main/docs/guide/provider.md" target="_blank" rel="noreferrer">https://github.com/gohade/hade/blob/main/docs/guide/provider.md</a>，并参考这篇文档创建一个 student provider。我们可以在配置文件中的 Docs 部分先增加这个文档源，并命名为 hade_provider_md。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/ce7002d306fca2896ba8f35483fb216c.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/ce7002d306fca2896ba8f35483fb216c.png" alt="图片"></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/a8f68cc6dfde892ff4caf7901b74846c.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/a8f68cc6dfde892ff4caf7901b74846c.png" alt="图片"></a></p><p>然后在 Composer 中输入这样的提示词：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/d190543a1eaa98yy136138f5c4750254.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/d190543a1eaa98yy136138f5c4750254.png" alt="图片"></a></p><p>最后的结果如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/08fa8905220140e7d47408913b444357.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/08fa8905220140e7d47408913b444357.png" alt="图片"></a></p><h3 id="git" tabindex="-1">Git <a class="header-anchor" href="#git" aria-label="Permalink to &quot;Git&quot;">​</a></h3><p>Git 也是非常好用的一个功能。你能用 @Git 来引出某个 commit、某个 merge，然后可以让 Cursor 对它们进行 codereview，并提出优化建议，提示词如下：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这次更新 @reorg space_cache 有哪些变动，做一下总结，并且提出一些优化建议</span></span></code></pre></div><p>输出结果如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/3accaff1191d09bc1baf6f31222b798d.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/3accaff1191d09bc1baf6f31222b798d.png" alt="图片"></a></p><h3 id="notepad" tabindex="-1">Notepad <a class="header-anchor" href="#notepad" aria-label="Permalink to &quot;Notepad&quot;">​</a></h3><p>在实际项目开发过程中，我们实际上是为了某个“需求”来提交多次的开发。那么这个需求就是我们的最终目标，我们需要完整描述它，也就是你想做什么，希望用什么框架来做。这就是 Cursor 提供的 Notepad 的功能。</p><p>我们可以使用 cmd+shift + i 打开 Notepad 面板，或者使用命令面板打开 Notepad 视图，创建一个新的 Notepad。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/d03a918b21ef0542bf9b48fc27d92a35.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/d03a918b21ef0542bf9b48fc27d92a35.png" alt="图片"></a></p><p>我们可以在 Notepad 上描述完整的需求，比如：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 我想要创建一个教学系统，表结构有 teacher，student，使用 gohade 进行实现。</span></span>
<span class="line"><span></span></span>
<span class="line"><span> 这个教学系统符合 gohade 框架的设计。</span></span>
<span class="line"><span></span></span>
<span class="line"><span> 教学系统有前台和后台。</span></span>
<span class="line"><span></span></span>
<span class="line"><span> 前台使用vue，后台使用 go。</span></span>
<span class="line"><span></span></span>
<span class="line"><span> teacher 的服务提供完整的provider，provider 中有增删改查操作。</span></span>
<span class="line"><span></span></span>
<span class="line"><span> student 的服务提供完整的provider，provider 中有完整的增删改查操作。</span></span></code></pre></div><p>这个需求当然是越精确越好。后面我们的每个命令都可以按照这个需求作为目标，来一步步实现。比如现在我们要实现 teacher 的 provider，就可以直接用提示词：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请按照 @system 思路，创建一个 teacher 的 provider。</span></span></code></pre></div><p>它就会按照我们专栏中 Hade 框架的逻辑，创建一个teacher 的 provider 了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/d02b7e7c7fffdca19ec17ec24ccfef69.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/d02b7e7c7fffdca19ec17ec24ccfef69.png" alt="图片"></a></p><p>我们通过不断更新和使用 Notepad，来告诉 Cursor 我们的目标，能有效保证模型每次生成的代码都是朝着我们的“需求”前进的。</p><h3 id="suggested" tabindex="-1">Suggested <a class="header-anchor" href="#suggested" aria-label="Permalink to &quot;Suggested&quot;">​</a></h3><p>这个功能我用得比较少。当你输入一个单词的时候，Cursor 会根据你的输入猜测你想改动哪个文件，并且在列表中给出建议。但是实际上，如果你有明确的修改目标，这个功能用得就不多了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/ea46b697ca0f4c0c202c12d235d1e80b.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/ea46b697ca0f4c0c202c12d235d1e80b.png" alt="图片"></a></p><h3 id="codebase" tabindex="-1">Codebase <a class="header-anchor" href="#codebase" aria-label="Permalink to &quot;Codebase&quot;">​</a></h3><p>Codebase 就代表整个项目，Cursor 不会将你的整个项目代码放到云上，但是以上的 Files、Folder、Code 又能很精准地定位到你项目中的某行代码，原理就是这个 Codebase。</p><p>它将你的项目代码向量化存储索引。每次你改动了项目中的代码，这 Codebase 就会重建。我们可以在 Cursor 的设置项中看到 Codebase 的 sync 进度。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/98ec771c7c4136795b0a2c4003c01dc2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/98ec771c7c4136795b0a2c4003c01dc2.png" alt="图片"></a></p><p>当我们在 Composer 中 @Codebase 的时候，就是希望 Cursor 能索引整个项目。这个对于大型的重构，或者阅读整个项目非常有用。</p><p>比如我要修改 Teacher 中的某个字段的类型，会涉及修改多个文件，当我将 Codebase 应用在提示词中的时候，模型就会去索引使用 Teacher 结构的文件，并且让模型分析这些使用的地方，给出修改建议。</p><p>提示词可以是：帮我分析下整个项目 @Codebase，告诉我有哪些文件使用了 @Teacher 这个数据结构，我需要将 CreateAt 属性修改为 time.Time。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/f16acfe13d87288a902b4da062f72ba2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/f16acfe13d87288a902b4da062f72ba2.png" alt="图片"></a></p><h3 id="web" tabindex="-1">Web <a class="header-anchor" href="#web" aria-label="Permalink to &quot;Web&quot;">​</a></h3><p>我们都知道，模型是需要预训练的，所以它里面的知识可能是旧的，那么我要如何获取互联网上最新的信息呢？这就要使用到 Web 了。</p><p>比如我想将项目中 Go 的版本升级到最新，我需要知道目前互联网上最新的版本是多少，那我就可以在 Composer 中使用 Web 这个提示词，告诉 Cursor 先去 Web 上查找下最新的 Go 版本，再做具体的操作。</p><p>提示词可以是：请问 @Web 最新的 Go 版本是多少，我想将我的项目 Go 升级为这个最新版本，要做哪些改动？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/da699898e0f8c854e0f3d7dc434afebe.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/da699898e0f8c854e0f3d7dc434afebe.png" alt="图片"></a></p><h2 id="cursor-如何赋能-golang-编程" tabindex="-1">Cursor 如何赋能 Golang 编程 <a class="header-anchor" href="#cursor-如何赋能-golang-编程" aria-label="Permalink to &quot;Cursor 如何赋能 Golang 编程&quot;">​</a></h2><p>我们说了这么多，基本把 Cursor 的常用用法都说清楚了。但是再厉害的武器，不知道如何使用它，也只是一堆废铁。那在 Golang 的业务开发过程中，我们该如何使用 Cursor 来提升效率呢？有哪些场景可以使用 Cursor 呢？</p><p>作为一名深度使用 Cursor 开发 Golang 业务长达半年的用户，我将以亲身使用经验告诉你，Cursor 是如何赋能 Golang 编程的。</p><h3 id="场景-1-批量操作" tabindex="-1">场景 1：批量操作 <a class="header-anchor" href="#场景-1-批量操作" aria-label="Permalink to &quot;场景 1：批量操作&quot;">​</a></h3><p>我这里说的批量操作场景指的并不是 IDE 中已经有的重命名函数、变量名这种简单的批量操作需求，而是一种模糊的批量操作场景，即一种更高维度的批量操作，我说几个例子你就明白了。</p><p>首先是批量增加注释。</p><p>一个文件夹中有很多函数，我在编写的时候忘记给函数增加注释了，在最后提交的时候，我希望为每个函数增加下注释。这时候我们可以在 Composer 中这样描述：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请帮我给 @lib 文件夹中的每个对外可见的函数增加注释，</span></span>
<span class="line"><span>要求注释以函数名开头，并且用中文描述。</span></span></code></pre></div><p>这样，就不需要你手动一个个函数修改，也不需要你理解函数内容，就能在多个文件中，为所有对外可见的函数增加符合规范的注释。</p><p>然后是批量修改日志。</p><p>在实际开发过程中，我的日志描述不是很标准，事先并没有思考很清楚，在代码 cr 的时候，leader 建议我给这个需求文件夹下的每个日志输出增加 [key_step] 的前缀。我不需要在一个个日志输出的地方修改，只需要在 Composer 中增加一句简单描述：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请帮我给 @lib 文件夹中的每个日志增加[key_step]的前缀，方便于进行日志的业务分析。</span></span></code></pre></div><p>你不用写一句代码，Cursor 就会修改这个文件夹中的每行日志，你所做的仅仅是点击下 accept all 按钮。</p><h3 id="场景2-单元测试" tabindex="-1">场景2：单元测试 <a class="header-anchor" href="#场景2-单元测试" aria-label="Permalink to &quot;场景2：单元测试&quot;">​</a></h3><p>Golang 是强类型语言，相较于弱类型语言，每个变量在定义时就决定了类型，其实很便于写单元测试。但是往往由于工期原因，我们在写一个函数或者类的时候，并不会为其写单元测试。</p><p>不过， <strong>时间在 Cursor 面前永远不是问题</strong>。</p><p>我们写完一个类、一个方法，在 Composer 中告诉 Cursor：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请帮我为 code @TeacherProvider 写单元测试，</span></span>
<span class="line"><span>要求使用table-driven 方法构造单测用例，</span></span>
<span class="line"><span>单元测试单独放一个文件中</span></span></code></pre></div><p>一段完善的、可运行的单元测试，就输出在我们面前了。</p><p>更美好的事情还在后面。当我们后续做业务迭代的时候，修改了某个类的结构或者修改了某个方法的输入参数和输出参数。我们可以让 Cursor 帮忙修改下测试用例。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我已经修改了 code @TeacherProvider 的结构，增加了一个Name 字段。</span></span>
<span class="line"><span>要求更改测试用例 @TestTeacherProvider 函数，增加 Name 字段的测试逻辑。</span></span>
<span class="line"><span>具体的 Name 赋值逻辑可以参考 code @TeacherProvider 的实现</span></span></code></pre></div><h3 id="场景3-源码阅读" tabindex="-1">场景3：源码阅读 <a class="header-anchor" href="#场景3-源码阅读" aria-label="Permalink to &quot;场景3：源码阅读&quot;">​</a></h3><p>我在实际工作中，经常需要阅读别人写的 Golang 函数，梳理一个很长的历史代码逻辑是很繁琐且耗时的事情。这个时候，我们希望的是有人能帮忙先读一下某个函数的实现逻辑，并且将逻辑用图形形式输出，辅助我理解。</p><p>这个情况我一般会使用 Chat：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮忙阅读一下 code @TeacherProvidor.Process 函数，</span></span>
<span class="line"><span>其中使用到的下一级别的函数逻辑可以在 @codebase 中查找。</span></span>
<span class="line"><span>绘制出这个函数的核心调用链路，用 markdown 的 mermaid 绘制出一个代码的流程图，</span></span>
<span class="line"><span>并将绘制的 markdown 放在 readme.md 文件中</span></span></code></pre></div><p>于是，Cursor 就会绘制出类似如下的代码流程图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/228fcf1e72c51567abc5ca76cf2eb394.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/228fcf1e72c51567abc5ca76cf2eb394.jpg" alt=""></a></p><p>跟着图再阅读代码，是不是就简单很多了？</p><h3 id="场景4-代码改写" tabindex="-1">场景4：代码改写 <a class="header-anchor" href="#场景4-代码改写" aria-label="Permalink to &quot;场景4：代码改写&quot;">​</a></h3><p>当已经有了旧实现方式，为了达成目的而使用新实现方式时，Cursor 就能很准确地参考旧的实现意图来实现新的方式。</p><p>这样说还是有点抽象，我举几个我实际遇到的情景。</p><p>情景一，现在我有一个库文件，其中有 10+ 个方法，原本是使用 Redis 的 lua 脚本实现某个逻辑。但在使用过程中发现了一个问题： Redis 多 slot 的问题导致 lua 脚本不可使用。经过紧急讨论，我们决定用 Redis 的 pipeline 替换原先的 lua。但棘手的是，留给我们重构的时间只有一个晚上了。</p><p>还是那句话，时间在 Cursor 面前不是问题。</p><p>我给 Cursor 的提示词如下：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>将 file @redis_op.go 文件中的涉及 lua 操作的函数都改写为使用 pipline 来操作redis。</span></span>
<span class="line"><span>其中要求：</span></span>
<span class="line"><span>1 新改写的 pipline 逻辑和之前的 lua 脚本逻辑是一致的</span></span>
<span class="line"><span>2 为新写的 pipline 逻辑增加测试用例</span></span></code></pre></div><p>一行命令下去，这 10+个方法在几分钟内都替换为 pipeline 的实现。我要做的只是验证测试。</p><p>情景二，我写了一段代码，是在 for 循环中调用 go() { Foo() } 的 RPC函数。这其实在高并发情况下可能会导致 goroutine 数量变多，我希望能控制 goroutine 的数量，于是就使用了如下脚本：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我把 code @TeacherProvider.List 函数重构下，</span></span>
<span class="line"><span>我希望最多只能出现 4 个 goroutine</span></span>
<span class="line"><span>任务通过 channel 传递给这4 个 goroutine。</span></span>
<span class="line"><span>这样我们就能控制 goroutine 数量了。</span></span></code></pre></div><p>Cursor 就帮我实现了一个简单的 goroutine 的协程池：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/71ea7cb87afe4086f31f553bc76579d3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E5%86%99%E4%B8%80%E4%B8%AAWeb%E6%A1%86%E6%9E%B6/images/844259/71ea7cb87afe4086f31f553bc76579d3.png" alt="图片"></a></p><p>我之前已经定义好 List 中的业务逻辑，所以 Cursor 只是修改了其中的并行度。对于这种有业务逻辑，只需要更新并发处理逻辑的任务，Cursor 一般能一次完美通过。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>现在，相信你对 Cursor 这个工具已经有了一个比较全面的认识。它不仅仅是一个简单的代码补全工具，而是一个真正能帮助我们提升开发效率的 AI 助手。</p><p>从最基础的 Tab 补全，到强大的 Composer 多文件编辑，再到各种 @ 符号的巧妙运用，Cursor 为我们提供了一整套完整的 AI 辅助开发解决方案。特别是它那些神奇的 @ 符号功能，真是让人越用越上瘾：想查最新文档用 @Web；要改多个文件用 @Codebase；需要参考文档就 @Docs。简直不要太方便！</p><p>不过，工具再好，也需要我们花时间去熟悉和掌握。建议你可以先从最基础的 Tab 补全开始用起，慢慢过渡到 Chat 和 Composer，等对这些基础功能熟悉了，再去尝试那些高级的 @ 符号功能。相信随着使用的深入，你一定会和我一样，爱上这个强大的 AI 编程助手。</p><p>最后我想说，AI 工具确实能帮我们提升效率，但它终究只是个工具。作为开发者，我们还是要不断学习，提升自己的编程能力。毕竟，能让 AI 产出更好代码的前提，是我们自己得先懂得什么是好代码，对吧？</p><p>好了，希望这篇文章能帮助你更好地使用 Cursor 做些 Golang 开发，如果你有什么使用心得，也欢迎在留言区和我一起交流分享！</p>`,147)])])}const g=a(i,[["render",o]]);export{b as __pageData,g as default};
